import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { fixedActionArgs } from '../../../rest-api';

/**
 * Fixed-action REST routes (`GET /api/{org}/connections`, `/runs`,
 * `/actions/available`, …) proxy to a tool with an action the SERVER picks.
 * They used to build args as `{ action: 'list', ...c.req.query() }` — the
 * caller's params spread last, so `?action=delete` replaced the route's own
 * action. `executeTool` still refused callers without the required access
 * level, so this was not privilege escalation; it was a write reachable by
 * GET. The session cookie is SameSite=Lax (`src/auth/routes.ts`), which is
 * sent on top-level cross-site GET navigations, so a plain link could make an
 * authorized member or admin perform the write:
 *
 *   GET /api/{org}/connections?action=delete&connection_id=5   -> admin delete
 *   GET /api/{org}/runs?action=approve&run_id=5                -> member approve
 *
 * The second one matters most: the approval gate exists to require a human
 * decision, and a crafted link supplied it.
 */

describe('fixed-action REST arg composition', () => {
  it('does not let a caller param replace the route\'s action', () => {
    const args = fixedActionArgs('list', {
      action: 'delete',
      connection_id: '5',
    });

    expect(args.action).toBe('list');
    expect(args.connection_id).toBe('5');
  });

  it('pins the action for every action a GET route could be steered to', () => {
    // Each of these is a write reachable through a route whose fixed action is
    // a read. Enumerated rather than spot-checked so a future composition
    // change cannot pass by getting only the first case right.
    for (const injected of [
