import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "bun:test";

/**
 * Class guard for the action-discriminator defect.
 *
 * `createActionCaller.action(name, input)` strips a caller-supplied `action`
 * key so it can never pick the handler — covered behaviourally by
 * `action-call.test.ts`. That guarantee is only worth anything if the
 * `actionName` argument is itself a literal. `entity-schema.ts` used to build
 * its payload first and then read the name back off it:
 *
 *   callEntity({ action: "list", ...input }, "listTypes")
 *   // -> action(payload.action as string, ...)
 *
 * so `listTypes({ action: "delete" })` dispatched a delete while the SDK
 * manifest had only admitted a read method. `executeTool` still re-checks the
 * caller's access level, so this was not privilege escalation for a low-tier
 * caller — but it defeated `query_sdk` read-mode for an admin one.
 *
 * A behavioural test of the namespace needs a live handler + DB, so this
 * asserts the shape instead: no namespace may derive its action name from
 * caller-supplied data.
 */

const NAMESPACE_DIR = join(__dirname, "../../../sandbox/namespaces");

function namespaceSources(): { file: string; src: string }[] {
	return readdirSync(NAMESPACE_DIR)
		.filter((f) => f.endsWith(".ts"))
		.map((file) => ({
			file,
			src: readFileSync(join(NAMESPACE_DIR, file), "utf8"),
		}));
}

describe("SDK namespace action discriminators", () => {
	it("never derives the action name from caller-supplied data", () => {
		// `action-call.ts` is the helper that *strips* the key; its own
		// destructuring reference is the one legitimate mention.
		const offenders = namespaceSources()
			.filter(({ file }) => file !== "action-call.ts")
			.filter(({ src }) =>
				/\b(payload|input|args|rest)\s*(\.|\[["'])action\b/.test(src)
			)
			.map(({ file }) => file);

		expect(offenders).toEqual([]);
	});

	it("finds at least one namespace to check", () => {
		// Guards against the glob silently matching nothing and passing vacuously.
		expect(namespaceSources().length).toBeGreaterThan(5);
	});
});

