import { describe, expect, it } from "bun:test";
import {
	PUBLIC_CONNECTION_FIELDS,
	projectConnectionForReader,
} from "../../../tools/admin/manage_connections/public-projection";
import type { ToolContext } from "../../../tools/registry";

/**
 * `manage_connections.list` / `.get` are in PUBLIC_READ_ACTIONS, so on a public
 * org they answer anonymous callers. Both select `c.*` plus a live
 * `connect_token` subselect and spread the row into the response.
 *
 * Verified anonymously against a prod public org before the fix: 49 fields
 * returned with no credentials, including `connect_token` (a one-hour bearer
 * capability), `created_by` and `created_by_username`.
 */

// The exact key set a prod public org returned to an unauthenticated caller.
const PROD_ROW: Record<string, unknown> = {
	id: 42,
	slug: "capterra-main",
	display_name: "Capterra",
	connector_key: "capterra",
	connector_name: "Capterra",
	status: "active",
	visibility: "org",
	created_at: "2026-05-01T00:00:00Z",
	updated_at: "2026-05-02T00:00:00Z",
	feed_count: 3,
	data_feed_count: 2,
	entity_ids: [1, 2],
	entity_names: "Acme, Globex",
	declares_chat: false,
	has_feeds_schema: true,
	has_operations: true,
	operations_summary: { total: 2 },
	facets: { data: true },
	// — everything below must never reach a non-member —
	connect_token: "ct_live_abc123",
	credentials: { token: "secret" },
	credential_mode: "byo",
	effective_credential_mode: "byo",
	config: { host: "internal.example" },
	created_by: "8a2D2Yb57odFHO2PldhD6n392Cf6456B",
	created_by_username: "buremba",
	account_id: "acct_9",
	external_tenant_id: "T0192",
	agent_id: "atlas-curator",
	auth_profile_id: 7,
	auth_profile_slug: "gh-main",
	auth_profile_name: "GitHub main",
	auth_profile_status: "active",
	auth_profile_kind: "oauth",
	app_auth_profile_id: 8,
	app_auth_profile_slug: "gh-app",
	app_auth_profile_name: "GitHub app",
	app_auth_profile_status: "active",
	app_auth_profile_kind: "app",
	device_label: "Burak's Mac",
	device_platform: "darwin",
	device_worker_id: "dw_5",
	device_worker_handle: "worker-5",
	device_last_seen_at: "2026-07-30T00:00:00Z",
	device_online: true,
	device_status: null,
	error_message: "connection refused to 10.1.2.3",
	unhealthy_alerted_at: null,
	deleted_at: null,
	organization_id: "org_25266d0da771e611",
};

const SENSITIVE = [
	"connect_token",
	"credentials",
	"credential_mode",
	"effective_credential_mode",
	"config",
	"created_by",
	"created_by_username",
	"account_id",
	"external_tenant_id",
	"agent_id",
	"auth_profile_id",
	"auth_profile_slug",
	"app_auth_profile_id",
	"device_label",
	"device_worker_handle",
	"device_last_seen_at",
	"error_message",
	"organization_id",
];

function ctxWith(memberRole: string | null): ToolContext {
	return {
		organizationId: "org_25266d0da771e611",
		userId: memberRole ? "u_1" : null,
		memberRole,
		isAuthenticated: !!memberRole,
	} as ToolContext;
}

describe("public connection projection", () => {
	it("withholds every sensitive field from an anonymous reader", () => {
		const projected = projectConnectionForReader(PROD_ROW, ctxWith(null));

		for (const key of SENSITIVE) {
			expect(projected).not.toHaveProperty(key);
		}
	});

	it("withholds a live connect token specifically", () => {
		// Called out on its own: it is a bearer capability, not metadata — it
		// resolves the connection and starts OAuth for an hour.
		const projected = projectConnectionForReader(PROD_ROW, ctxWith(null));

		expect(projected.connect_token).toBeUndefined();
		expect(Object.values(projected)).not.toContain("ct_live_abc123");
	});

	it("withholds it from an authenticated NON-member too", () => {
		// A public org admits a signed-in non-member with memberRole: null.
		// They are exactly as unentitled as an anonymous caller.
		const projected = projectConnectionForReader(PROD_ROW, {
			...ctxWith(null),
			userId: "u_outsider",
			isAuthenticated: true,
		} as ToolContext);

		expect(projected).not.toHaveProperty("connect_token");
		expect(projected).not.toHaveProperty("created_by");
	});

	it("still returns what a public connectors listing renders", () => {
		const projected = projectConnectionForReader(PROD_ROW, ctxWith(null));

		expect(projected.id).toBe(42);
		expect(projected.display_name).toBe("Capterra");
		expect(projected.connector_key).toBe("capterra");
		expect(projected.status).toBe("active");
		expect(projected.feed_count).toBe(3);
		expect(projected.entity_names).toBe("Acme, Globex");
	});

	it("leaves a member's row untouched", () => {
		// The console reads the full row; narrowing members would break it.
		for (const role of ["owner", "admin", "member"]) {
			expect(projectConnectionForReader(PROD_ROW, ctxWith(role))).toEqual(
				PROD_ROW
			);
		}
	});

	it("is an allow-list, so an unknown future column is withheld by default", () => {
		// The property that makes this fail closed: a column added to
		// `connections` later must not leak until someone remembers to exclude it.
		const projected = projectConnectionForReader(
			{ ...PROD_ROW, some_future_secret: "leak" },
			ctxWith(null)
		);

		expect(projected).not.toHaveProperty("some_future_secret");
	});

	it("never lists a sensitive field in the allow-list itself", () => {
		// Guards the allow-list against being widened into a leak later.
		for (const key of SENSITIVE) {
			expect(PUBLIC_CONNECTION_FIELDS.has(key)).toBe(false);
		}
	});
});

