import type { Context } from "hono";

/**
 * REST GET routes that are nothing but a fixed `(tool, action)` proxy.
 *
 * These exist so the REST door and the tool door answer the SAME question with
 * the SAME policy. `PUBLIC_READ_ACTIONS` declares which `(tool, action)` pairs a
 * public organization may serve anonymously, but `canAccessPublicOrgRequest`
 * could only ever see a tool name on a JSON POST body — a `GET /api/{org}/runs`
 * carried no tool name, so it was denied even though
 * `POST /api/{org}/manage_operations {"action":"list_runs"}` returned the same
 * rows with 200. Same data, two doors, opposite answers.
 *
 * Declaring the pair here closes that gap without widening policy: the
 * middleware resolves the matched route to a declaration and asks the existing
 * `isPublicReadable`. Nothing becomes public that the tool door did not already
 * serve.
 *
 * The table is also what registers the routes (see `index.ts`), so a route's
 * declared `(tool, action)` and the pair it actually executes cannot drift.
 *
 * ONLY pure proxies belong here. A route with a hand-rolled handler — the agent
 * list, `/installed` — returns a superset of its tool's payload, so its
 * declaration would claim a public-readability its response does not honour.
 * Those need an explicit public projection first; see `public-projection.ts`
 * under `manage_connections` for the shape.
 */
export type RestToolRoute = {
	/** Hono route pattern, matched against `routePath(c, -1)`. */
	readonly routePath: string;
	readonly tool: string;
	readonly action: string;
	/** Caller-supplied args. `action` is pinned by `restToolAction`, not here. */
	readonly args: (c: Context) => Record<string, unknown>;
};

export const REST_TOOL_GET_ROUTES: readonly RestToolRoute[] = [
	{
		routePath: "/api/:orgSlug/connections",
		tool: "manage_connections",
		action: "list",
		args: (c) => c.req.query(),
	},
	{
		routePath: "/api/:orgSlug/connections/:id",
		tool: "manage_connections",
		action: "get",
		args: (c) => ({ connection_id: Number(c.req.param("id")) }),
	},
	{
		routePath: "/api/:orgSlug/runs",
		tool: "manage_operations",
		action: "list_runs",
		args: (c) => c.req.query(),
	},
	{
		routePath: "/api/:orgSlug/actions/available",
		tool: "manage_operations",
		action: "list_available",
		args: (c) => c.req.query(),
	},
];

const BY_ROUTE_PATH: ReadonlyMap<string, RestToolRoute> = new Map(
	REST_TOOL_GET_ROUTES.map((route) => [route.routePath, route])
);

/**
 * Resolve a matched Hono route pattern to its declaration.
 *
 * Undeclared paths — and Hono's `/*` catch-all for an unmatched request —
 * simply miss the map, so the caller denies. Fail-closed by construction.
 */
export function lookupRestToolGetRoute(
	resolvedRoutePath: string
): RestToolRoute | undefined {
	return BY_ROUTE_PATH.get(resolvedRoutePath);
}

